const request = $input.first().json;
const headers = request.headers || {};
const secret = $vars.VAPI_WEBHOOK_SECRET;
if (!secret) throw new Error('Set the VAPI_WEBHOOK_SECRET n8n variable before activating this workflow.');
const authorization = headers.authorization || headers.Authorization || '';
if (authorization !== `Bearer ${secret}`) return [{ json: { statusCode: 401, response: { error: 'Unauthorized' } } }];
const input = request.body || request;
const message = input.message || input;
const call = message.call || {};
const callId = String(call.id || message.callId || '');
const phone = String((call.customer && call.customer.number) || (message.customer && message.customer.number) || 'Unknown caller');
const supabaseUrl = String($vars.SUPABASE_URL || '').replace(/\/$/, '');
const supabaseKey = $vars.SUPABASE_SERVICE_ROLE_KEY;
if (!supabaseUrl || !supabaseKey) throw new Error('Set SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY in n8n variables.');
const apiHeaders = { apikey: supabaseKey, Authorization: `Bearer ${supabaseKey}`, 'Content-Type': 'application/json' };
async function db(path, method = 'GET', body, prefer) {
  const response = await fetch(`${supabaseUrl}/rest/v1/${path}`, { method, headers: { ...apiHeaders, ...(prefer ? { Prefer: prefer } : {}) }, ...(body === undefined ? {} : { body: JSON.stringify(body) }) });
  const text = await response.text();
  if (!response.ok) throw new Error(`Supabase ${response.status}: ${text}`);
  return text ? JSON.parse(text) : null;
}
async function saveCall(values) {
  if (!callId) return;
  await db('calls?on_conflict=call_id', 'POST', { call_id: callId, phone, ...values }, 'resolution=merge-duplicates,return=minimal');
}
function result(toolCallId, value) {
  return { toolCallId, result: JSON.stringify(value) };
}
const type = message.type || '';
if (type === 'status-update' && ['ringing', 'in-progress'].includes(message.status)) {
  await saveCall({});
  return [{ json: { response: { received: true } } }];
}
if (type === 'end-of-call-report') {
  const artifact = message.artifact || call.artifact || {};
  const started = Date.parse(call.startedAt || '');
  const ended = Date.parse(call.endedAt || '');
  const duration = Number.isFinite(started) && Number.isFinite(ended) ? Math.max(0, Math.round((ended - started) / 1000)) : null;
  await saveCall({ duration_s: duration, summary: message.analysis?.summary || message.summary || null, transcript: artifact.transcript || message.transcript || null, recording_url: artifact.recordingUrl || call.recordingUrl || null });
  return [{ json: { response: { received: true } } }];
}
if (type !== 'tool-calls') return [{ json: { response: { received: true } } }];
if (!callId) throw new Error('Vapi tool call did not include a call ID.');
await saveCall({});
const toolCalls = message.toolCallList || message.toolWithToolCallList || [];
const results = [];
for (const entry of toolCalls) {
  const tool = entry.toolCall || entry;
  const functionCall = tool.function || {};
  const toolCallId = String(tool.id || entry.id || '');
  const name = String(functionCall.name || entry.name || tool.name || '');
  let args = functionCall.arguments || functionCall.parameters || tool.parameters || tool.arguments || {};
  if (typeof args === 'string') args = JSON.parse(args);
  try {
    if (name === 'get_menu') {
      const menu = await db('menu_items?available=eq.true&select=name,description,price,category&order=category,name');
      results.push(result(toolCallId, { items: menu || [] }));
    } else if (name === 'save_order') {
      if (args.confirmed !== true) throw new Error('The caller must explicitly confirm the complete order before it can be saved.');
      const type = args.type;
      if (!['pickup', 'delivery'].includes(type)) throw new Error('Order type must be pickup or delivery.');
      const address = String(args.address || '').trim();
      if (type === 'delivery' && address.length < 8) throw new Error('A complete delivery address is required.');
      const items = Array.isArray(args.items) ? args.items : [];
      if (!items.length) throw new Error('At least one order item is required.');
      const existing = await db(`orders?call_id=eq.${encodeURIComponent(callId)}&select=id&limit=1`);
      if (existing && existing.length) { results.push(result(toolCallId, { success: true, already_saved: true, message: 'An order is already saved for this call.' })); continue; }
      const menu = await db('menu_items?available=eq.true&select=name,price');
      const lines = items.map((line) => {
        const item = menu.find((row) => row.name.toLocaleLowerCase('en-US') === String(line.name || '').trim().toLocaleLowerCase('en-US'));
        const quantity = Number(line.quantity);
        if (!item || !Number.isInteger(quantity) || quantity < 1 || quantity > 50) throw new Error('Order includes an unavailable menu item or invalid quantity.');
        const unit = Number(item.price);
        return { name: item.name, quantity, unit_price: unit, line_total: Math.round(unit * quantity * 100) / 100 };
      });
      const total = Math.round(lines.reduce((sum, line) => sum + line.line_total, 0) * 100) / 100;
      const confirmedTotal = Number(args.confirmed_total);
      if (!Number.isFinite(confirmedTotal) || Math.abs(confirmedTotal - total) > 0.01) throw new Error('The confirmed total does not match the current menu prices. Read back the correct total and ask for confirmation again.');
      const eta = type === 'delivery' ? 45 : 20;
      await db('orders', 'POST', { call_id: callId, customer_name: String(args.customer_name || '').trim() || null, phone: String(args.phone || phone), type, address: type === 'delivery' ? address : null, items: lines, total, eta_minutes: eta, status: 'new', notes: String(args.notes || '').trim() || null }, 'return=representation');
      results.push(result(toolCallId, { success: true, total, eta_minutes: eta, message: `Order saved. Total ${total.toFixed(2)} euros; estimated ${eta} minutes.` }));
    } else if (name === 'save_booking') {
      if (args.confirmed !== true) throw new Error('The caller must explicitly confirm the complete reservation before it can be saved.');
      const customerName = String(args.customer_name || '').trim();
      const date = String(args.date || '');
      const time = String(args.time || '');
      const partySize = Number(args.party_size);
      if (!customerName || !/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(time) || !Number.isInteger(partySize) || partySize < 1 || partySize > 30) throw new Error('Reservation details are missing or invalid.');
      const existing = await db(`bookings?call_id=eq.${encodeURIComponent(callId)}&select=id&limit=1`);
      if (existing && existing.length) { results.push(result(toolCallId, { success: true, already_saved: true, message: 'A reservation is already saved for this call.' })); continue; }
      await db('bookings', 'POST', { call_id: callId, customer_name: customerName, phone: String(args.phone || phone), date, time, party_size: partySize, notes: String(args.notes || '').trim() || null, status: 'confirmed' }, 'return=representation');
      results.push(result(toolCallId, { success: true, message: `Reservation saved for ${date} at ${time} for ${partySize} people.` }));
    } else {
      results.push(result(toolCallId, { success: false, error: `Unknown Vapi tool: ${name}` }));
    }
  } catch (error) {
    results.push({ toolCallId, error: error instanceof Error ? error.message : 'The request failed.' });
  }
}
return [{ json: { response: { results } } }];
